// h264/ring_words_mem.sv -- the HPS interface's status words whose sources are on clk_mem (generated by tools/ring_layout.py -- edit the tables there, never this file).
// A mux on the word index: combinational, the index quasi-static (h264/ring_stat.sv holds
// it through the snapshot). Words of other domains read 0 here.

`default_nettype none

module ring_words_mem (
    input  wire  [5:0]  ix,
    input  wire  [31:0] f_read_index,        // w5: the released index: the core needs nothing below it, so the program may overwrite it (0.5: held behind the oldest AUDIO record not yet fetched to play)
    input  wire  [31:0] f_ack_nonce,         // w5: the nonce of the session the core runs
    input  wire  [31:0] f_n_polls,           // w11: reads of the program's words
    input  wire  [31:0] f_n_bursts,          // w11: ring read bursts
    input  wire  [7:0] f_eng_err,           // w12: the engine's error (ERR_WIDX_*)
    input  wire  [0:0] f_eng_session,       // w12: the engine runs a session
    input  wire  [31:0] f_eng_widx,          // w12: the write index the engine last read
    input  wire  [31:0] f_fetch_changes,     // w13: disp_reader: shown (store, parity) changes fetched (never reset per stream)
    input  wire  [15:0] f_probe_busy,        // w13: ram1: the current run of a request held under waitrequest
    input  wire  [31:0] f_probe_wr,          // w28: ram1 write beats
    input  wire  [31:0] f_probe_rd,          // w28: ram1 read beats
    input  wire  [15:0] f_probe_owed,        // w29: ram1 read beats owed
    input  wire  [15:0] f_probe_busy_max,    // w29: ram1 longest busy run
    output logic [63:0] w
);
    always_comb begin
        w = 64'd0;
        case (ix)
            6'd5: begin w[31:0] = f_read_index; w[63:32] = f_ack_nonce; end
            6'd11: begin w[31:0] = f_n_polls; w[63:32] = f_n_bursts; end
            6'd12: begin w[7:0] = f_eng_err; w[8:8] = f_eng_session; w[63:32] = f_eng_widx; end
            6'd13: begin w[31:0] = f_fetch_changes; w[47:32] = f_probe_busy; end
            6'd28: begin w[31:0] = f_probe_wr; w[63:32] = f_probe_rd; end
            6'd29: begin w[15:0] = f_probe_owed; w[31:16] = f_probe_busy_max; end
            default: ;
        endcase
    end
endmodule

`default_nettype wire
